-- the pool model: every table carries the tenant, and the database enforces it even if a handler forgets
alter table invoices enable row level security;
create policy tenant_isolation on invoices
  using (tenant_id = current_setting('app.tenant_id')::uuid);

-- the API sets the session's tenant from the verified token before any query
set local app.tenant_id = '2f9c3a4e-...';
